(function () {
  var L = window.LP.quiz;
  [
   {"id": "m01-p1", "m": "m01", "q": "Was kennzeichnet CAS laut JP 3-09.3?", "o": ["requires detailed integration of each air mission with the fire and movement of those forces", "targets more than 10 km from friendly forces", "always requires a FAC(A)", "is flown only by rotary-wing aircraft"], "a": 0, "e": "<span class=\"qt\">2. Close Air Support Overview a. CAS is air action by fixed-wing (FW) and rotary-wing (RW) aircraft against hostile targets that are in close proximity to friendly forces and requires detailed integration of each air mission with the fire and movement of those forces.</span>", "src": [["jp3093", "p. I-1"]]},
   {"id": "m01-p2", "m": "m01", "q": "Was ist Terminal Attack Control?", "o": ["the authority to control the maneuver of and grant weapons release clearance to attacking aircraft", "the transmission of target coordinates to the aircraft", "the marking of a target with a laser", "the approval of fires by the fire support coordinator"], "a": 0, "e": "<span class=\"qt\">e. TAC. TAC is the authority to control the maneuver of and grant weapons release clearance to attacking aircraft.</span>", "src": [["jp3093", "p. I-2"]]},
   {"id": "m01-p3", "m": "m01", "q": "Was darf ein JFO laut JP 3-09.3?", "o": ["request, adjust, and control surface-to-surface fires, provide targeting information in support of Type 2 and 3 CAS TACs, and perform TGO", "grant weapons release clearance in Type 2 control", "perform Type 1 control when no JTAC is present", "approve reattacks"], "a": 0, "e": "<span class=\"qt\">(5) JFO. A JFO is a qualified and certified Service member who can request, adjust, and control surface-to-surface fires, provide targeting information in support of Type 2 and 3 CAS TACs, and perform TGO in conjunction with a JTAC/FAC(A).</span>", "src": [["jp3093", "p. II-10"]]},
   {"id": "m01-p4", "m": "m01", "q": "Welche Aufgabe hat der TAC(A) im TACS?", "o": ["communications relay between the TACP and attack aircraft", "terminal attack control of all CAS aircraft", "approval of all immediate requests", "mensuration of target coordinates"], "a": 0, "e": "<span class=\"qt\">(d) TAC(A). The TAC(A) is an extension of air support control agencies. In the TACS, TAC(A) provides communications relay between the TACP and attack aircraft, as well as other agencies of the TACS, in the absence of JSTARS, or a FAC(A).</span>", "src": [["jp3093", "p. II-8"]]},
   {"id": "m01-p5", "m": "m01", "q": "Welche zwei Missionsarten nennt AJP-3.3 für Counter-Surface-Force-Operationen?", "o": ["air interdiction (AI) and close air support (CAS)", "strategic attack and AI", "CAS and SCAR", "AI and offensive counter-air"], "a": 0, "e": "<span class=\"qt\">Operations generally fall under two mission types: air interdiction (AI) and close air support (CAS).</span>", "src": [["ajp33", "p. 28"]]},
   {"id": "m01-p6", "m": "m01", "q": "Was gehört nicht zu den Bedingungen für wirksames CAS?", "o": ["favorable weather", "effective C2", "target marking and/or acquisition", "appropriate ordnance"], "a": 0, "e": "<span class=\"qt\">The conditions for effective CAS are: thoroughly trained personnel with well-developed skills, effective planning and integration, effective C2, air superiority (especially suppression of enemy air defenses [SEAD]), target marking and/or acquisition, streamlined and flexible procedures, and appropriate ordnance. Although not a requirement for CAS employment, favorable environmental conditions improve CAS effectiveness.</span>", "src": [["jp3093", "p. I-6"]]},
   {"id": "m01-p7", "m": "m01", "q": "Wer ist der Hauptberater des Bodenkommandeurs für Luftoperationen?", "o": ["ALO", "JTAC", "FSO", "TAC(A)"], "a": 0, "e": "<span class=\"qt\">(a) ALO. The ALO is the senior TACP member attached to a ground unit who functions as the primary advisor to the ground commander on air operations.</span>", "src": [["jp3093", "p. II-6"]]},
   {"id": "m02-p1", "m": "m02", "q": "Welche Arten von CAS-Anforderungen gibt es?", "o": ["preplanned and immediate", "scheduled and alert", "deliberate and dynamic", "routine and priority"], "a": 0, "e": "<span class=\"qt\">Air support requests are used to identify the supported commander’s requirements for CAS and other supporting air missions. There are two types of CAS requests: preplanned and immediate.</span>", "src": [["jp3093", "p. III-127"]]},
   {"id": "m02-p2", "m": "m02", "q": "Was bedeutet Schweigen einer Zwischenebene bei einer Immediate Request?", "o": ["consent to the request", "denial of the request", "the request is on hold", "the request must be resubmitted"], "a": 0, "e": "<span class=\"qt\">Silence by intermediate HQ implies consent to the request.</span>", "src": [["jp3093", "p. III-130"]]},
   {"id": "m02-p3", "m": "m02", "q": "Für welchen Zeitraum gilt eine ATO normalerweise?", "o": ["24 hours", "12 hours", "48 hours", "72 hours"], "a": 0, "e": "<span class=\"qt\">4.15 The ATO articulates tasking for air operations for a specific time, normally 24 hours.</span>", "src": [["ajp33", "p. 44"]]},
   {"id": "m02-p4", "m": "m02", "q": "Welches Netz verbindet ASOC und unterstellte TACPs für Immediate Requests?", "o": ["JARN", "TAD", "Guard", "TAR"], "a": 0, "e": "<span class=\"qt\">(g) JARN. The JARN is the link between the ASOC and subordinate TACPs for aircraft coordination and sending immediate air support requests.</span>", "src": [["jp3093", "p. II-25"]]},
   {"id": "m02-p5", "m": "m02", "q": "Wofür dient das TAD-Netz?", "o": ["a means for the control of aircraft", "emergency distress traffic", "requesting immediate air support", "inflight reports"], "a": 0, "e": "<span class=\"qt\">(i) TAD Net. The TAD net provides a means for the control of aircraft.</span>", "src": [["jp3093", "p. II-26"]]},
   {"id": "m02-p6", "m": "m02", "q": "Mit welchem Formular wird CAS über ASOC/DASC angefordert?", "o": ["JTAR (DD 1972)", "USMTF MISREP", "INFLTREP", "ASR D670 only"], "a": 0, "e": "<span class=\"qt\">(5) Request Format. The JTAR (DD 1972) is used for requesting CAS through the ASOC/DASC.</span>", "src": [["jp3093", "p. III-131"]]},
   {"id": "m02-p7", "m": "m02", "q": "Was ist die ASOC?", "o": ["the principal air control agency within the TACS, responsible for controlling joint air operations that directly support ground forces", "the senior element of the TACS", "a USMC air command and control agency", "an airborne extension of the TACP"], "a": 0, "e": "<span class=\"qt\">(4) ASOC. The ASOC is the principal air control agency within the TACS, responsible for controlling joint air operations that directly support ground forces.</span>", "src": [["jp3093", "p. II-6"]]},
   {"id": "m03-p1", "m": "m03", "q": "Wie ist der CAS-Entscheidungsprozess aufgebaut?", "o": ["a continuous three-phase cycle", "a linear five-step process", "a two-phase cycle", "a six-phase air tasking cycle"], "a": 0, "e": "<span class=\"qt\">The CAS decision-making process, as indicated in Figure III-1, is a continuous three-phase cycle that has been tailored for joint fire support and focused specifically on CAS.</span>", "src": [["jp3093", "p. III-1"]]},
   {"id": "m03-p2", "m": "m03", "q": "Auf welcher Wahrscheinlichkeit beruhen Risk-Estimate Distances?", "o": ["0.1 percent Pi (1 in 1,000)", "1 percent Pi (1 in 100)", "10 percent Pi", "0.01 percent Pi"], "a": 0, "e": "<span class=\"qt\">(10) Risk Estimate Distance (a) Risk estimate distances allow the supported commander to estimate the potential danger to friendly troops from the CAS attack. They are discussed as 0.1 percent probability of incapacitation (Pi) (i.e., 1 in 1,000 Pi).</span>", "src": [["jp3093", "p. III-36"]]},
   {"id": "m03-p3", "m": "m03", "q": "Wer muss bei Danger Close die Verantwortung für das Risiko übernehmen?", "o": ["the supported commander", "the JTAC", "the flight lead", "the ASOC"], "a": 0, "e": "<span class=\"qt\">(b) Danger Close. Ordnance delivery inside the 0.1 percent Pi distance will be considered “danger close.” The supported commander must accept responsibility for the risk to friendly forces when targets are inside the 0.1 percent Pi distance.</span>", "src": [["jp3093", "p. III-37"]]},
   {"id": "m03-p4", "m": "m03", "q": "Was ist Positive Identification?", "o": ["reasonable certainty that the entity or object is a valid military target and the correct target", "visual confirmation by two observers", "a mensurated coordinate", "a TALLY by the aircrew"], "a": 0, "e": "<span class=\"qt\">3-92. Positive identification is reasonable certainty that the entity or object is a valid military target and the correct target.</span>", "src": [["atp30930", "p. 3-24"]]},
   {"id": "m03-p5", "m": "m03", "q": "Was ist Battle Tracking?", "o": ["the process of building and maintaining an overall picture of the operational environment that is accurate, timely, and relevant", "tracking of attack aircraft on the TAD", "the BDA log", "a target list for the ATO"], "a": 0, "e": "<span class=\"qt\">a. Battle Tracking. Battle tracking is the process of building and maintaining an overall picture of the operational environment that is accurate, timely, and relevant.</span>", "src": [["jp3093", "p. III-32"]]},
   {"id": "m03-p6", "m": "m03", "q": "Was ist Combat Identification?", "o": ["the process of attaining an accurate characterization of detected objects sufficient to support an engagement decision", "the identification of friendly aircraft by IFF", "the PID of a single target", "the correlation between JTAC and aircrew"], "a": 0, "e": "<span class=\"qt\">combat identification. The process of attaining an accurate characterization of detected objects in the operational environment sufficient to support an engagement decision. Also called CID. (JP 1-02. SOURCE: JP 3-09)</span>", "src": [["jp309", "p. GL-6"]]},
   {"id": "m04-p1", "m": "m04", "q": "Welche Type of Control: JTAC muss Luftfahrzeug und Ziel bei jedem Angriff sehen?", "o": ["Type 1", "Type 2", "Type 3", "BOT"], "a": 0, "e": "<span class=\"qt\">(1) Type 1 Control. Type 1 control is used when the JTAC/FAC(A) requires control of individual attacks and the situation requires the JTAC/FAC(A) to visually acquire the attacking aircraft and visually acquire the target for each attack.</span>", "src": [["jp3093", "p. I-2"]]},
   {"id": "m04-p2", "m": "m04", "q": "Welche Type of Control: Einzelangriffe, JTAC sieht das Luftfahrzeug beim Waffeneinsatz nicht oder das Ziel nicht?", "o": ["Type 2", "Type 1", "Type 3", "BOC"], "a": 0, "e": "<span class=\"qt\">(2) Type 2 Control. Type 2 control is used when the JTAC/FAC(A) requires control of individual attacks and is unable to visually acquire the attacking aircraft at weapons release or is unable to visually acquire the target.</span>", "src": [["jp3093", "p. I-2"]]},
   {"id": "m04-p3", "m": "m04", "q": "Welche Type of Control: Freigabe für mehrere Angriffe in einem Engagement?", "o": ["Type 3", "Type 2", "Type 1", "BOT"], "a": 0, "e": "<span class=\"qt\">(3) Type 3 Control. Type 3 control is used when the JTAC/FAC(A) requires the ability to provide clearance for multiple attacks within a single engagement subject to specific attack restrictions.</span>", "src": [["jp3093", "p. I-2"]]},
   {"id": "m04-p4", "m": "m04", "q": "Wie verhalten sich Method of Attack und Type of Control zueinander?", "o": ["separate and independent constructs", "Type 1 always requires BOT", "BOC is only allowed with Type 3", "Type 2 always requires BOC"], "a": 0, "e": "<span class=\"qt\">b. Methods of Attack. The method of attack and type of control are separate and independent constructs.</span>", "src": [["jp3093", "p. III-47"]]},
   {"id": "m04-p5", "m": "m04", "q": "Wie oft ist Korrelation erforderlich?", "o": ["on each and every CAS attack", "only for BOT attacks", "only in Type 1 control", "only for the first attack of a flight"], "a": 0, "e": "<span class=\"qt\">In CAS, correlation is the process by which the JTAC/FAC(A) coordinates and confirms that the attacking aircrew, and/or a third-party contributor, have acquired the correct target or mark. Correlation is required on each and every CAS attack.</span>", "src": [["jp3093", "p. III-47"]]},
   {"id": "m04-p6", "m": "m04", "q": "Wer liest bei BOC Line 4 und Line 6 zurück?", "o": ["all aircraft delivering ordnance, from their system or weapon", "only the lead aircraft", "only the last aircraft", "no one, BOC needs no readback"], "a": 0, "e": "<span class=\"qt\">(b) For BOC missions, all aircraft delivering ordnance must read back Line 4 and Line 6 from their system or weapon, as appropriate, in conjunction with other required restrictions.</span>", "src": [["jp3093", "p. III-48"]]},
   {"id": "m04-p7", "m": "m04", "q": "Was ist ABORT?", "o": ["term used by a JTAC/FAC(A) during all types of control to terminate the attack prior to weapons release", "a call only used in Type 1 control", "the command to destroy a weapon in flight", "a request for a new 9-line"], "a": 0, "e": "<span class=\"qt\">(1) ABORT. Term used by a JTAC/FAC(A) during all types of control to terminate the attack prior to weapons release.</span>", "src": [["jp3093", "p. III-40"]]},
   {"id": "m04-p8", "m": "m04", "q": "Was ist ein Post-Launch Abort?", "o": ["deliberate action taken post-separation to cause a precision munition to miss its target", "an abort before weapons release", "a cancelled CAS request", "an aircraft returning to base"], "a": 0, "e": "<span class=\"qt\">post-launch abort. Deliberate action taken post-separation to cause a precision munition to miss its target. Also called PLA. (Approved for inclusion in JP 1-02.)</span>", "src": [["jp3093", "p. GL-12"]]},
   {"id": "m05-p1", "m": "m05", "q": "Was ist das Minimum im Game Plan?", "o": ["type of control and method of attack", "ordnance and fuzing", "TOT and egress", "target elevation and location"], "a": 0, "e": "<span class=\"qt\">(4) Game Plan. A concise means to inform all players of the flow of the upcoming attack. Minimum information shall include type of control and method of attack.</span>", "src": [["jp3093", "p. V-20"]]},
   {"id": "m05-p2", "m": "m05", "q": "Was muss der JTAC neu eingecheckten Luftfahrzeugen sofort mitteilen?", "o": ["other AOS, their call sign, operating altitude, and frequency", "the full 9-line", "the abort code", "the BDA of earlier attacks"], "a": 0, "e": "<span class=\"qt\">(1) Routing/Safety of Flight. JTAC/FAC(A) should immediately advise newly checked-in aircraft of other AOS, their call sign, operating altitude, and frequency, as soon as possible.</span>", "src": [["jp3093", "p. V-14"]]},
   {"id": "m05-p3", "m": "m05", "q": "Welche Zeilen des Situation Update werden übermittelt?", "o": ["only those lines that apply", "always all lines", "only threat and friendlies", "only the lines requested by the aircrew"], "a": 0, "e": "<span class=\"qt\">(b) Only those lines that apply should be passed.</span>", "src": [["jp3093", "p. V-20"]]},
   {"id": "m05-p4", "m": "m05", "q": "Was bedeutet Sequential Timing?", "o": ["aircraft will attack one at a time with a specific interval between each aircraft", "all aircraft attack at the same time", "aircraft attack at random", "aircraft attack from different sectors simultaneously"], "a": 0, "e": "<span class=\"qt\">2. Sequential Timing. Aircraft will attack one at a time with a specific interval between each aircraft.</span>", "src": [["jp3093", "p. V-5"]]},
   {"id": "m05-p5", "m": "m05", "q": "Wozu dient das Situation Update?", "o": ["to increase all players’ SA to the level required by the tactical situation", "to pass the CAS brief", "to authenticate the aircraft", "to report BDA"], "a": 0, "e": "<span class=\"qt\">(3) Situation Update (a) The situation update brief is a tool used to increase all players’ SA to the level required by the tactical situation.</span>", "src": [["jp3093", "p. V-17"]]},
   {"id": "m06-p1", "m": "m06", "q": "Welche Elemente des 9-Line sind Pflicht-Readback?", "o": ["lines 4, 6, and restrictions", "lines 1, 4 and 6", "lines 6 and 8 only", "all nine lines"], "a": 0, "e": "<span class=\"qt\">(7) Readbacks (a) Required readbacks of lines 4, 6, and restrictions.</span>", "src": [["jp3093", "p. V-33"]]},
   {"id": "m06-p2", "m": "m06", "q": "Was verlangt die NATO-ATP zusätzlich als Readback?", "o": ["Line 8", "Line 9", "Line 3", "Line 7"], "a": 0, "e": "<span class=\"qt\">Note: NATO Allied Tactical Publication 3.3.2.1, TTP for Close Air Support and Air Interdiction, requires Line 8 to be a mandatory readback item. When working with NATO FACs/JTACs, aircrew should be prepared to read back Line 8 as part of the mandatory readback items.</span>", "src": [["jp3093", "p. V-30"]]},
   {"id": "m06-p3", "m": "m06", "q": "In welcher Einheit wird Line 3 für Starrflügler angegeben?", "o": ["nautical miles, accurate to a tenth", "kilometers", "meters", "statute miles"], "a": 0, "e": "<span class=\"qt\">(f) Line 3―Distance. The distance is given from the IP/BP to the target. For fixed wing aircraft, the distance is given in nautical miles and should be accurate to a tenth of a nautical mile.</span>", "src": [["jp3093", "p. V-26"]]},
   {"id": "m06-p4", "m": "m06", "q": "Wie wird die Zielhöhe (Line 4) angegeben?", "o": ["in feet MSL", "in meters HAE", "in feet AGL", "in meters MSL"], "a": 0, "e": "<span class=\"qt\">(g) Line 4―Target Elevation. The target elevation is given in feet MSL.</span>", "src": [["jp3093", "p. V-26"]]},
   {"id": "m06-p5", "m": "m06", "q": "Wie wird Line 8 angegeben?", "o": ["cardinal/sub-cardinal heading from the target and distance of closest friendly position from the target in meters", "grid of the closest friendly position", "bearing from the friendlies to the target in degrees", "distance from the IP in nautical miles"], "a": 0, "e": "<span class=\"qt\">(k) Line 8-Friendlies. Cardinal/sub-cardinal heading from the target (N, NE, E, SE, S, SW, W, or NW) and distance of closest friendly position from the target in meters (e.g., “South 300”).</span>", "src": [["jp3093", "p. V-30"]]},
   {"id": "m06-p6", "m": "m06", "q": "Was gilt immer als Restriction?", "o": ["FAHs, ACAs, danger close, and TOTs", "egress and LTL", "ordnance and fuzing", "threat and SEAD"], "a": 0, "e": "<span class=\"qt\">(b) If issued, FAHs, ACAs, danger close, and TOTs shall always be considered restrictions and will be read back.</span>", "src": [["jp3093", "p. V-33"]]},
   {"id": "m06-p7", "m": "m06", "q": "Was sagt die NATO-ATP zu Line-Titeln?", "o": ["NATO FACs will pass line titles for each line in a CAS brief", "line titles are never passed", "only line numbers are passed", "line titles only for lines 4 and 6"], "a": 0, "e": "<span class=\"qt\">Note: Allied Tactical Publication 3.3.2.1, TTP for Close Air Support and Air Interdiction, directs that NATO FACs will pass line titles for each line in a CAS brief.</span>", "src": [["jp3093", "p. V-26"]]},
   {"id": "m06-p8", "m": "m06", "q": "Was ist Line 1?", "o": ["the IP or BP; the IP is the starting point for the run-in to the target", "the target location", "the heading from the IP", "the egress point"], "a": 0, "e": "<span class=\"qt\">(d) Line 1–IP or BP. The IP is the starting point for the run-in to the target.</span>", "src": [["jp3093", "p. V-26"]]},
   {"id": "m07-p1", "m": "m07", "q": "Was bedeutet TALLY?", "o": ["sighting of a target, nonfriendly aircraft, or enemy position", "sighting of a friendly aircraft or ground position", "sighting of a reference point", "sensor has acquired the target"], "a": 0, "e": "<span class=\"qt\">TALLY Sighting of a target, nonfriendly aircraft, or enemy position. Opposite of NO JOY.</span>", "src": [["jp3093", "p. III-78"]]},
   {"id": "m07-p2", "m": "m07", "q": "Was bedeutet VISUAL?", "o": ["sighting of a FRIENDLY aircraft or ground position", "sighting of the target", "laser spot acquired", "IR mark acquired"], "a": 0, "e": "<span class=\"qt\">VISUAL Sighting of a FRIENDLY aircraft or ground position. Opposite of BLIND.</span>", "src": [["jp3093", "p. III-78"]]},
   {"id": "m07-p3", "m": "m07", "q": "Was bedeutet CAPTURED?", "o": ["specified surface target or object has been acquired and is being tracked with an onboard sensor", "the target has been destroyed", "the aircraft is visual with the JTAC", "the laser code is set"], "a": 0, "e": "<span class=\"qt\">(target/object) CAPTURED – Specified surface target or object has been acquired and is being tracked with an onboard sensor.</span>", "src": [["jp3093", "p. III-78"]]},
   {"id": "m07-p4", "m": "m07", "q": "Welches Verhältnis empfiehlt JP 3-09.3 beim Talk-on?", "o": ["two directive statements, then a confirming question", "one statement, one question", "three statements, then a question", "only questions"], "a": 0, "e": "<span class=\"qt\">o. A two-to-one ratio should be used when conducting talk-ons. Give two directive statements, then ask a confirming question of the aircrew.</span>", "src": [["jp3093", "p. V-44"]]},
   {"id": "m07-p5", "m": "m07", "q": "Wie bewegt man mit SLEW den Sensor?", "o": ["up, down, left, and right instead of cardinal directions", "cardinal directions only", "clock positions", "mils from the reticle"], "a": 0, "e": "<span class=\"qt\">e. When using the term SLEW to directively move a sensor, JTACs should use up, down, left, and right instead of cardinal directions, to avoid confusion.</span>", "src": [["jp3093", "p. V-45"]]},
   {"id": "m07-p6", "m": "m07", "q": "Darf FMV allein zur Zielidentifizierung genutzt werden?", "o": ["no, not as a single-source target identification method", "yes, if the VDL is HANDSHAKE", "yes, in Type 3 control", "yes, for BOC attacks"], "a": 0, "e": "<span class=\"qt\">FMV feeds should not be used as a single-source target identification method.</span>", "src": [["jp3093", "p. III-118"]]},
   {"id": "m08-p1", "m": "m08", "q": "Was darf eine Besatzung nicht als alleinige Zielidentifizierung nutzen?", "o": ["LSTs", "the targeting pod", "the JTAC talk-on", "visual acquisition"], "a": 0, "e": "<span class=\"qt\">WARNING Aircrews shall not use LSTs as the sole source for target identification.</span>", "src": [["jp3093", "p. III-54"]]},
   {"id": "m08-p2", "m": "m08", "q": "Was bedeutet TEN SECONDS?", "o": ["standby for LASER ON call in approximately 10 seconds", "ten seconds to impact", "lase for ten seconds", "ten seconds to weapons release"], "a": 0, "e": "<span class=\"qt\">TEN SECONDS Standby for LASER ON call in approximately 10 seconds.</span>", "src": [["jp3093", "p. III-79"]]},
   {"id": "m08-p3", "m": "m08", "q": "Was bedeutet SPOT?", "o": ["acquisition of laser designation", "laser designator inoperative", "start lasing", "laser energy not acquired"], "a": 0, "e": "<span class=\"qt\">SPOT Acquisition of laser designation</span>", "src": [["jp3093", "p. III-79"]]},
   {"id": "m08-p4", "m": "m08", "q": "Was bedeutet DEAD EYE?", "o": ["laser designator system inoperative", "laser energy has not been acquired", "aircrew does not see the IR mark", "video data link lost"], "a": 0, "e": "<span class=\"qt\">DEAD EYE Laser designator system inoperative.</span>", "src": [["jp3093", "p. III-79"]]},
   {"id": "m08-p5", "m": "m08", "q": "Was bedeutet SNAKE?", "o": ["oscillate an IR pointer in a figure eight about a target", "circle an IR pointer around an aircraft", "flashing IR energy", "stop oscillation of the IR pointer"], "a": 0, "e": "<span class=\"qt\">SNAKE Oscillate an IR pointer in a figure eight about a target.</span>", "src": [["jp3093", "p. III-80"]]},
   {"id": "m08-p6", "m": "m08", "q": "Welche Warnung gilt für ROPE?", "o": ["this technique may damage night vision devices", "only for rotary wing aircraft", "only with a laser code", "only in Type 1 control"], "a": 0, "e": "<span class=\"qt\">ROPE Circling an IR pointer around an aircraft to help the aircraft identify the friendly ground position. Caution: This technique may damage night vision devices.</span>", "src": [["jp3093", "p. III-80"]]},
   {"id": "m08-p7", "m": "m08", "q": "Darf die Besatzung übermittelte IAM-Koordinaten anpassen?", "o": ["no, not for any reason", "yes, to correct TLE", "yes, if the JTAC agrees", "yes, for moving targets"], "a": 0, "e": "<span class=\"qt\">Aircrew will not adjust coordinates that are passed and put into the system for any reason.</span>", "src": [["jp3093", "p. III-62"]]},
   {"id": "m09-p1", "m": "m09", "q": "Was ist TLE?", "o": ["the difference between the coordinates generated for a target and the actual location of the target", "the circular error of the weapon", "the error of the aircraft INS", "the elevation error of the map"], "a": 0, "e": "<span class=\"qt\">target location error. The difference between the coordinates generated for a target and the actual location of the target. Also called TLE. (Approved for incorporation into JP 1- 02.)</span>", "src": [["jp3093", "p. GL-13"]]},
   {"id": "m09-p2", "m": "m09", "q": "Welcher Höhenbezug gilt standardmäßig für die Zielhöhe?", "o": ["ft MSL", "m HAE", "ft AGL", "m MSL"], "a": 0, "e": "<span class=\"qt\">(a) Target Elevation (Line 4). The default target elevation is in ft MSL.</span>", "src": [["jp3093", "p. V-1"]]},
   {"id": "m09-p3", "m": "m09", "q": "Was sagt die Anzahl der Ziffern einer Gitterkoordinate aus?", "o": ["the level of precision of the grid, not a measurement of accuracy", "the accuracy of the target location", "the TLE category", "the datum used"], "a": 0, "e": "<span class=\"qt\">4. The number of digits in a grid coordinate is the level of precision of the grid, not a measurement of accuracy.</span>", "src": [["jp3093", "p. V-28"]]},
   {"id": "m09-p4", "m": "m09", "q": "Welcher Kreisbruchteil ist ein Mil?", "o": ["1/6400 of the circumference of a circle", "1/6000 of the circumference", "1/360 of the circumference", "1/1000 of the circumference"], "a": 0, "e": "<span class=\"qt\">3-20. A mil is a unit of measure for angles that is based on the angle subtended by l/6400 of the circumference of a circle (TC 3-09.81).</span>", "src": [["atp30930", "p. 3-3"]]},
   {"id": "m09-p5", "m": "m09", "q": "Was ist der Observer-Target Factor?", "o": ["the distance in meters from the observer to the target expressed to the nearest thousand and in thousands", "the angle between OT line and GT line", "the observer’s height above the target", "the mil spotting multiplied by 1,000"], "a": 0, "e": "<span class=\"qt\">3-26. The observer-target factor is the distance in meters from the observer to the target expressed to the nearest thousand and in thousands.</span>", "src": [["atp30930", "p. 3-5"]]},
   {"id": "m09-p6", "m": "m09", "q": "Was ist Mensuration?", "o": ["the process of measurement of a feature or location on the Earth to determine an absolute latitude, longitude, and height", "the estimation of distance with binoculars", "the transformation between datums", "the reading of a grid from a map"], "a": 0, "e": "<span class=\"qt\">(c) Target coordinate mensuration is the process of measurement of a feature or location on the Earth to determine an absolute latitude, longitude, and height.</span>", "src": [["jp3093", "p. III-33"]]},
   {"id": "m10-p1", "m": "m10", "q": "Was ist eine ACA?", "o": ["a three-dimensional block of airspace in a target area in which friendly aircraft are reasonably safe from friendly surface fires", "an area into which fires are prohibited", "a line beyond which fires need no coordination", "a holding area for helicopters"], "a": 0, "e": "<span class=\"qt\">airspace coordination area. A three-dimensional block of airspace in a target area, established by the appropriate commander, in which friendly aircraft are reasonably safe from friendly surface fires. Also called ACA. (Approved for incorporation into JP 1- 02.)</span>", "src": [["jp3093", "p. GL-8"]]},
   {"id": "m10-p2", "m": "m10", "q": "Was ist eine NFA?", "o": ["an area into which fires or their effects are prohibited", "an area in which specific restrictions are imposed", "an area into which any weapon system may fire without additional coordination", "a line between converging forces"], "a": 0, "e": "<span class=\"qt\">no-fire area. An area designated by the appropriate commander into which fires or their effects are prohibited. Also called NFA. (JP 1-02. SOURCE: JP 3-09.3)</span>", "src": [["jp3093", "p. GL-12"]]},
   {"id": "m10-p3", "m": "m10", "q": "Was ist eine RFL?", "o": ["a line established between converging friendly surface forces that prohibits fires or their effects across that line", "a line beyond which surface fires may fire at any time", "the forward edge of the battle area", "a line short of which all fires must be coordinated with the land commander"], "a": 0, "e": "<span class=\"qt\">restrictive fire line. A line established between converging friendly surface forces that prohibits fires or their effects across that line. Also called RFL. (JP 1-02. SOURCE: JP 3- 09)</span>", "src": [["jp309", "p. GL-9"]]},
   {"id": "m10-p4", "m": "m10", "q": "Was ist TOT?", "o": ["the actual time at which munitions impact the target", "the time the aircraft leaves the IP", "the time of weapons release", "the minutes and seconds after a hack"], "a": 0, "e": "<span class=\"qt\">time on target. The actual time at which munitions impact the target. Also called TOT. (JP 1-02. SOURCE: JP 3-09.3)</span>", "src": [["jp3093", "p. GL-14"]]},
   {"id": "m10-p5", "m": "m10", "q": "Was ist TTT?", "o": ["the number of minutes and seconds to elapse before aircraft ordnance impacts on target", "the time on target in Zulu", "the time of flight of the weapon", "the time the aircraft is on station"], "a": 0, "e": "<span class=\"qt\">time to target. The number of minutes and seconds to elapse before aircraft ordnance impacts on target. Also called TTT. (JP 1-02. SOURCE: JP 3-09.3)</span>", "src": [["jp3093", "p. GL-14"]]},
   {"id": "m10-p6", "m": "m10", "q": "Was sagt die Offset Direction?", "o": ["on which side of the IP-to-target line the aircrew can maneuver for the attack", "the egress direction", "the direction of the friendlies", "the final attack heading"], "a": 0, "e": "<span class=\"qt\">(c) Offset Direction. The offset direction tells the aircrew on which side of the IP-to-target line they can maneuver for the attack (see Figure III-19).</span>", "src": [["jp3093", "p. III-75"]]},
   {"id": "m10-p7", "m": "m10", "q": "Wozu dient der Keyhole Template?", "o": ["establishing an IP in the absence of control points", "deconflicting surface fires", "assigning final attack headings", "reporting BDA"], "a": 0, "e": "<span class=\"qt\">1. Keyhole template is an efficient method for establishing an IP in the absence of control points or when their location does not sufficiently support target engagement (see Figure III-18).</span>", "src": [["jp3093", "p. III-74"]]},
   {"id": "m10-p8", "m": "m10", "q": "Was ist das primäre Ziel von SEAD?", "o": ["to allow friendly aircraft to operate in airspace defended by an enemy air defense system", "to destroy all enemy air defenses", "to guarantee aircraft immunity", "to mark the target"], "a": 0, "e": "<span class=\"qt\">1. The primary objective of SEAD is to allow friendly aircraft to operate in airspace defended by an enemy air defense system, including the target area and ingress/egress routes.</span>", "src": [["jp3093", "p. III-81"]]},
   {"id": "m11-p1", "m": "m11", "q": "Welche Elemente hat ein Call for Fire?", "o": ["observer identification, warning order, target location, target description, method of engagement and method of fire and control", "warning order, grid, direction, description, MTO", "call sign, grid, altitude, target, ammunition, splash", "observer, target, friendlies, egress, remarks, TOT"], "a": 0, "e": "<span class=\"qt\">4-8. The six elements of a call for fire include: observer identification, warning order, target location, target description, method of engagement and method of fire and control.</span>", "src": [["atp30930", "p. 4-2"]]},
   {"id": "m11-p2", "m": "m11", "q": "Ab welcher Entfernung ist ein Steilfeuer-Auftrag (Mörser/Artillerie) DANGER CLOSE?", "o": ["600 meters", "750 meters", "1,000 meters", "400 meters"], "a": 0, "e": "<span class=\"qt\">4-34. DANGER CLOSE is included in the method of engagement when the target is (or rounds will impact) within 600 meters of any friendly troops for mortars and artillery, 750 meters for 5 inch naval guns and tomahawk land attack missile (also TLAM).</span>", "src": [["atp30930", "p. 4-5"]]},
   {"id": "m11-p3", "m": "m11", "q": "Welche Entfernung gilt bei 5-inch-Schiffsgeschützen und TLAM für DANGER CLOSE?", "o": ["750 meters", "600 meters", "1,000 meters", "1,500 meters"], "a": 0, "e": "<span class=\"qt\">4-34. DANGER CLOSE is included in the method of engagement when the target is (or rounds will impact) within 600 meters of any friendly troops for mortars and artillery, 750 meters for 5 inch naval guns and tomahawk land attack missile (also TLAM).</span>", "src": [["atp30930", "p. 4-5"]]},
   {"id": "m11-p4", "m": "m11", "q": "Wann sendet die FDC SPLASH?", "o": ["5 seconds prior to round impact", "10 seconds prior to impact", "at round impact", "when the rounds are fired"], "a": 0, "e": "<span class=\"qt\">4-63. Send SPLASH at the observer's request. The FDC announces SPLASH to the observer 5 seconds prior to round impact.</span>", "src": [["atp30930", "p. 4-8"]]},
   {"id": "m11-p5", "m": "m11", "q": "Welche Korrekturen nutzt Creeping Fire bei Danger Close?", "o": ["corrections of 100 meters or less", "corrections of 200 meters", "bold shifts of 400 meters", "only deviation corrections"], "a": 0, "e": "<span class=\"qt\">5-51. Use the creeping fire method of adjustment during danger close missions. The observer should make range changes by creeping the rounds to the target, using corrections of 100 meters or less, rather than making large range corrections.</span>", "src": [["atp30930", "p. 5-12"]]},
   {"id": "m11-p6", "m": "m11", "q": "Wie wird eine Seitenkorrektur angesagt?", "o": ["opposite the spotting", "in the direction of the spotting", "always in mils", "only after the range correction"], "a": 0, "e": "<span class=\"qt\">5-16. Announce the computed deviation correction to the FDC as LEFT (or RIGHT) (so much). The correction is opposite the spotting.</span>", "src": [["atp30930", "p. 5-5"]]},
   {"id": "m11-p7", "m": "m11", "q": "Was ist der Standard-Mission-Type ohne Ankündigung bei der Zielortung?", "o": ["grid", "polar", "shift from a known point", "laser grid"], "a": 0, "e": "<span class=\"qt\">4-20. Grid is the standard method of target location and when used is not announced in the warning order.</span>", "src": [["atp30930", "p. 4-3"]]},
   {"id": "m11-p8", "m": "m11", "q": "Darf der JFO CLEARED HOT geben?", "o": ["no, the JFO will not issue weapons release authority", "yes, in Type 2 control", "yes, if the JTAC delegates it", "yes, for surface fires only"], "a": 0, "e": "<span class=\"qt\">(3) While the JFO will not issue weapons release authority (i.e., CLEARED HOT), informing him of weapons release from the aircraft allows the JFO time to notify ground forces to seek cover if required.</span>", "src": [["jp3093", "p. V-67"]]},
   {"id": "m12-p1", "m": "m12", "q": "Ab welcher Höhe beginnen Medium/High Altitude Tactics?", "o": ["approximately 8,000 ft AGL", "3,000 ft AGL", "15,000 ft AGL", "10,000 ft MSL"], "a": 0, "e": "<span class=\"qt\">(2) Medium/High Altitude Tactics. Medium/high altitude tactics are flown above approximately 8,000 ft AGL.</span>", "src": [["jp3093", "p. III-84"]]},
   {"id": "m12-p2", "m": "m12", "q": "Was ist bei Drehflüglern „Low“?", "o": ["below 500 ft AGL", "below 1,000 ft AGL", "below 3,000 ft AGL", "below 100 ft AGL"], "a": 0, "e": "<span class=\"qt\">(a) High. Above 3,000 ft AGL.<br><br>(b) Medium. 500-to-3,000 ft AGL.<br><br>(c) Low. Below 500 ft AGL.</span>", "src": [["jp3093", "p. III-90"]]},
   {"id": "m12-p3", "m": "m12", "q": "Wer muss Reattacks genehmigen?", "o": ["the JTAC/FAC(A), after coordination with the ground force commander", "the flight lead", "the ASOC", "the TAC(A)"], "a": 0, "e": "<span class=\"qt\">2. The JTAC/FAC(A) must approve reattacks (after coordination with the ground force commander).</span>", "src": [["jp3093", "p. III-82"]]},
   {"id": "m12-p4", "m": "m12", "q": "Ist die Übermittlung des RW CAS 5-Line eine Feuerfreigabe?", "o": ["no, it is still considered a CAS brief and does not constitute clearance to fire", "yes, like the SOF gunship call for fire", "yes, in Type 3 control", "only if “At my command” is omitted"], "a": 0, "e": "<span class=\"qt\">5-line briefs is that the RW CAS 5-line is still considered a CAS brief, and transmission of the brief itself does not constitute clearance to fire.</span>", "src": [["jp3093", "p. III-95"]]},
   {"id": "m12-p5", "m": "m12", "q": "Was gehört beim RW CAS 5-Line zum Readback?", "o": ["all restrictions", "lines 4 and 6", "only the target location", "nothing"], "a": 0, "e": "<span class=\"qt\">(6) Readbacks for a RW CAS 5-line should include all restrictions.</span>", "src": [["jp3093", "p. III-96"]]},
   {"id": "m12-p6", "m": "m12", "q": "Was ist eine Show of Force?", "o": ["an operation designed to demonstrate resolve that involves increased visibility of deployed forces", "a dry pass in Type 1 control", "a strafing attack near civilians", "a reconnaissance pass"], "a": 0, "e": "<span class=\"qt\">A show of force is an operation designed to demonstrate resolve that involves increased visibility of deployed forces in an attempt to defuse a specific situation.</span>", "src": [["jp3093", "p. III-108"]]},
   {"id": "m12-p7", "m": "m12", "q": "Ist eine digitale Information bei DACAS eine Freigabe?", "o": ["no, digital information does not substitute or constitute clearance", "yes, with a digital readback", "yes, in BOC attacks", "yes, if the track quality is high"], "a": 0, "e": "<span class=\"qt\">–Presence or lack of digital information does not substitute or constitute clearance; and,</span>", "src": [["jp3093", "p. III-114"]]},
   {"id": "m12-p8", "m": "m12", "q": "Wer hat beim Abflug Vorrang?", "o": ["aircraft egressing from the target", "aircraft ingressing to the target", "the flight lead", "rotary-wing aircraft"], "a": 0, "e": "<span class=\"qt\">1. Aircraft egressing from the target have the right-of-way.</span>", "src": [["jp3093", "p. III-82"]]},
   {"id": "m13-p1", "m": "m13", "q": "Wer darf jederzeit ABORT rufen?", "o": ["anyone", "only the JTAC", "only the flight lead", "only the JTAC and FAC(A)"], "a": 0, "e": "<span class=\"qt\">1. Once an aircraft calls IN, all other calls should be held until after the JTAC has issued weapons-release authority or an abort. An exception to this is that anyone can and should call an abort at any time they deem necessary.</span>", "src": [["jp3093", "p. V-46"]]},
   {"id": "m13-p2", "m": "m13", "q": "Wie wird ohne gebrieften Abort Code abgebrochen?", "o": ["ABORT, ABORT, ABORT", "ABORT DELTA", "KNOCK-IT-OFF", "CEASE FIRE"], "a": 0, "e": "<span class=\"qt\">If no abort code was briefed, then the CAS attack is aborted by simply transmitting: ABORT, ABORT, ABORT (see Figure V-11).</span>", "src": [["jp3093", "p. V-47"]]},
   {"id": "m13-p3", "m": "m13", "q": "Wofür steht SALTR?", "o": ["size, activity, location, time, remarks", "situation, aircraft, location, target, results", "size, altitude, location, type, readback", "strike, assessment, location, time, report"], "a": 0, "e": "<span class=\"qt\">2. The JTAC/FAC(A) should provide a “SALTR [size, activity, location, time, remarks]” report to the appropriate C2 agency to determine if further assets are required.</span>", "src": [["jp3093", "p. V-49"]]},
   {"id": "m13-p4", "m": "m13", "q": "Was gibt der JTAC mindestens weiter, wenn kein BDA möglich ist?", "o": ["SUCCESSFUL, UNSUCCESSFUL, or UNKNOWN", "GOOD HITS", "NO JOY", "nothing"], "a": 0, "e": "<span class=\"qt\">If conditions preclude briefing BDA, at a minimum pass SUCCESSFUL, UNSUCCESSFUL, or UNKNOWN assessment to the aircraft and the controlling agency;</span>", "src": [["jp3093", "p. V-49"]]},
   {"id": "m13-p5", "m": "m13", "q": "Für wen wird BDA gegeben?", "o": ["for a flight, not individual aircraft", "for each aircraft", "only for the lead", "only to the ASOC"], "a": 0, "e": "<span class=\"qt\">(d) BDA reports may be passed throughout the TOS, or prior to aircraft egressing, and should be given for a flight, not individual aircraft.</span>", "src": [["jp3093", "p. V-49"]]},
   {"id": "m13-p6", "m": "m13", "q": "Wie lautet der Call für einen Reattack auf dasselbe Ziel?", "o": ["“Call sign, CONTINUE for a reattack, restrictions remain the same.”", "“Call sign, CLEARED HOT, reattack.”", "“Call sign, new 9-line follows.”", "“Call sign, cleared to engage.”"], "a": 0, "e": "<span class=\"qt\">(d) If the reattack is against the same target, the JTAC should state “Call sign, CONTINUE for a reattack, restrictions remain the same.”</span>", "src": [["jp3093", "p. V-48"]]},
   {"id": "m13-p7", "m": "m13", "q": "Mit welchem Format meldet die Besatzung Missionsergebnisse im Flug?", "o": ["INFLTREP", "MISREP", "SALTR", "JTAR"], "a": 0, "e": "<span class=\"qt\">(f) Aircrew Responsibilities. Use the abbreviated USMTF INFLTREP (Figure V-12) to report CAS mission results.</span>", "src": [["jp3093", "p. V-49"]]},
   {"id": "m14-p1", "m": "m14", "q": "Welche ATP regelt die TTP für CAS und AI in der NATO?", "o": ["ATP-3.3.2.1", "ATP-3.3.3.1", "ATP-3.3.5.1", "ATP 3-09.32"], "a": 0, "e": "<span class=\"qt\">13. Subordinate tactical publications, designated Allied tactical publications (ATPs), contain further supporting details in the form of tactics, techniques and procedures which include ATP-3.3.2.1, Tactics, Techniques and Procedures for Close Air Support and Air Interdiction, ATP-3.3.3.1, Air-Maritime Coordination Procedures (AMCP) and ATP-3.3.5.1, Joint Airspace Control Tactics, Techniques and Procedures.</span>", "src": [["ajp33", "p. xix"]]},
   {"id": "m14-p2", "m": "m14", "q": "Welcher Keystone-Publikation ist AJP-3.3 unterstellt?", "o": ["AJP-3", "AJP-01", "AJP-3.3.2", "AAP-6"], "a": 0, "e": "<span class=\"qt\">12. AJP-3.3 is subordinate to the keystone publication AJP-3.</span>", "src": [["ajp33", "p. xix"]]},
   {"id": "m14-p3", "m": "m14", "q": "Was bedeutet ** bei einem Begriff in ATP 1-02.1?", "o": ["not a NATO brevity word", "meaning differs from the NATO brevity word", "air-to-surface only", "obsolete term"], "a": 0, "e": "<span class=\"qt\">** Not a NATO brevity word.</span>", "src": [["atp1021", "p. 1"]]},
   {"id": "m14-p4", "m": "m14", "q": "Was bedeutet * bei einem Begriff in ATP 1-02.1?", "o": ["meaning differs from the NATO brevity word", "not a NATO brevity word", "general brevity code", "maritime only"], "a": 0, "e": "<span class=\"qt\">* Meaning differs from the North Atlantic Treaty Organization (NATO) brevity word.</span>", "src": [["atp1021", "p. 1"]]},
   {"id": "m14-p5", "m": "m14", "q": "Was nutzt die NATO laut JP 3-09.3 als Grundlage für CAS?", "o": ["JP 3-09.3", "ATP 3-09.32", "FM 3-09", "JP 3-52"], "a": 0, "e": "<span class=\"qt\">26. Planning for Multinational Operations a. NATO and partner nations have and continue to use JP 3-09.3, Close Air Support, as a basis for conducting CAS.</span>", "src": [["jp3093", "p. III-127"]]}
  ].forEach(function (x) { L.push(x); });
})();
